      if (k === 0) s = right ? t('stem.numberline.ms_right_mark', 'Its right end lines up with the {w}-inch mark.') : t('stem.numberline.ms_left_mark', 'Its left end lines up with the {w}-inch mark.');
      else if (item.rd === 8) s = k === 1
